-- Paso 2: Poblar product_barcodes desde products insertados
INSERT OR IGNORE INTO product_barcodes (product_id, barcode, label) SELECT id, barcode, 'Principal' FROM products WHERE barcode IS NOT NULL AND barcode != '' AND id NOT IN (SELECT product_id FROM product_barcodes);
